//! 🧪️ Actual producer-owned output pages preserve their backing until exact paid handback and retirement.
use super::*;
#[cfg_attr(test,test)]
pub fn original_owned_output_loan_keeps_paid_producer_and_exact_handback(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let expected:Vec<u8>=serde_json::from_value(law["bytes"].clone()).unwrap();
 for copy in [1,3,64]{let mut lane=Lane::new(10000);let policy=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:1048576,maximum_release_bytes:1048576,maximum_depth:128};
 loop{let input=lane.checkout(policy);let(call,system)=observe(||lane.entry.admit_step(input));let ready=call.result.unwrap().ready;lane.receive(input,call.receipt_spent,call.work_units_spent,system,if ready{ActorGuestPhase::Ready}else{ActorGuestPhase::Pending});if ready{break}}
 let mut source=None;let input=lane.checkout(RetainedCloneGrant{maximum_copy_bytes:expected.len(),maximum_capacity_bytes:97,..policy});let budget=lane.budget(input);let mut recipient=Default::default();let(call,system)=observe(||lane.entry.dispatch_value_step(input,budget,&mut recipient,clock,|cx|{let mut bytes=Vec::with_capacity(97);bytes.extend_from_slice(&expected);source=Some(bytes);cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:expected.len(),retained_capacity_bytes:97,..Default::default()})?;cx.consume_fuel(1);Ok::<_,ValueError>(())}));assert!(call.result.is_ok());lane.receive(input,call.receipt_spent,call.work_units_spent,system,ActorGuestPhase::Dispatched);let source_pointer=source.as_ref().unwrap().as_ptr();let input=lane.checkout(policy);let budget=lane.budget(input);let mut recipient=Default::default();let(call,system)=observe(||lane.entry.dispatch_job_step(11,input,budget,&mut recipient,clock,|cx|{cx.consume_retained(RetainedCloneProgress{copied_items:1,..Default::default()})?;cx.consume_fuel(1);Ok(Some(OriginalJobStep::Done(source.take().unwrap())))},|_,_|Ok(false)));assert!(matches!(call.result,Ok(None)));lane.receive(input,call.receipt_spent,call.work_units_spent,system,ActorGuestPhase::Dispatched);
 let mut received=[0u8;7];let mut received_len=0;let mut closed=false;for turn in 0..10000{let demand=lane.entry.original_job_output_demands(copy).unwrap();let input=lane.checkout(RetainedCloneGrant{maximum_copy_bytes:copy.max(demand.copy_bytes),..policy});let budget=lane.budget(input);let mut recipient=Default::default();let(call,system)=observe(||lane.entry.read_job_output_borrowed_step(11,input,budget,&mut recipient,clock,false));let metadata=call.result.unwrap();let header=OriginalOwnedJobCall{input:call.input,spent:call.receipt_spent,work_units_spent:call.work_units_spent,status:OriginalOwnedJobStatus::Output{chunk:Some(metadata),source_closed:false},refusal:None};let(mut receipt,heap)=observe(||{let mut receipt=OriginalOwnedJobFixedReceipt::empty();receipt.write(header);receipt});assert_eq!(heap,(0,0));let(read,heap)=observe(||OriginalOwnedJobFixedReceipt::read(receipt.bytes()).unwrap());assert_eq!(heap,(0,0));assert_eq!(read.input,input);assert_eq!(read.spent,call.receipt_spent);assert_eq!(read.work_units_spent,call.work_units_spent);receipt.write(read);assert_eq!(observe(||drop(receipt)).1,(0,0));
 if let Some(length)=metadata.byte_length{let length=length as usize;let view=lane.entry.borrow_job_output_chunk(11,71,3,metadata.offset,length as u64).unwrap();let pointer=view.as_ptr();assert!(length<=copy);received[received_len..received_len+length].copy_from_slice(view);received_len+=length;assert_eq!(call.receipt_spent.copied_bytes,length);assert_eq!(system.0,call.receipt_spent.retained_capacity_bytes);assert_eq!(system.1,0);assert_eq!(call.work_units_spent,1);lane.receive(input,call.receipt_spent,call.work_units_spent,system,ActorGuestPhase::Dispatched);
 for identity in [(12,71,3),(11,72,3),(11,71,4)]{assert!(lane.entry.borrow_job_output_chunk(identity.0,identity.1,identity.2,metadata.offset,length as u64).is_none())}assert!(lane.entry.borrow_job_output_chunk(11,71,3,metadata.offset+1,length as u64).is_none());assert!(lane.entry.borrow_job_output_chunk(11,71,3,metadata.offset,length as u64+1).is_none());let OriginalJobStep::Done(bytes)=lane.entry.original_job_output().unwrap()else{panic!("original output source changed")};assert_eq!(bytes.as_ptr(),source_pointer);
 let input=lane.checkout(policy);let budget=lane.budget(input);let mut recipient=Default::default();let calls=CLOCK_CALLS.load(std::sync::atomic::Ordering::Relaxed);let(call,system)=observe(||lane.entry.read_job_output_step(11,input,budget,&mut recipient,clock,true));assert!(call.result.is_err());assert_eq!(call.receipt_spent,Default::default());assert_eq!(call.work_units_spent,0);assert_eq!(CLOCK_CALLS.load(std::sync::atomic::Ordering::Relaxed),calls);assert_eq!(lane.entry.context.cancellation_is_cancelled(),Some(false));lane.receive(input,call.receipt_spent,call.work_units_spent,system,ActorGuestPhase::Dispatched);
 let input=lane.checkout(policy);let budget=lane.budget(input);let mut recipient=Default::default();let(call,system)=observe(||lane.entry.close_jobs_step(input,budget,&mut recipient,clock,&mut EmptyOriginalJobs));assert!(!call.result.unwrap());assert_eq!(call.receipt_spent,Default::default());assert_eq!(call.work_units_spent,0);assert_eq!(system,(0,0));lane.receive(input,call.receipt_spent,call.work_units_spent,system,ActorGuestPhase::Dispatched);
 for denial in 0..5{if denial==2{let before=lane.issued;let(result,system)=observe(||lane.host.checkout_guest(RetainedCloneGrant{maximum_items:0,..policy}));assert!(result.unwrap().is_none());assert_eq!(system,(0,0));assert_eq!(lane.issued,before);assert_eq!(lane.entry.borrow_job_output_chunk(11,71,3,metadata.offset,length as u64).unwrap().as_ptr(),pointer);continue}let input=lane.checkout(policy);let budget=StepBudget::new(if denial==3{0}else{lane.fuel},if denial==4{100}else{u64::MAX},input.grant);let mut recipient=Default::default();let calls=CLOCK_CALLS.load(std::sync::atomic::Ordering::Relaxed);let(call,system)=observe(||lane.entry.acknowledge_job_output_chunk_step(if denial==0{12}else{11},metadata.offset,if denial==1{length as u64+1}else{length as u64},input,budget,&mut recipient,clock));if denial<2{assert!(call.result.is_err());assert_eq!(CLOCK_CALLS.load(std::sync::atomic::Ordering::Relaxed),calls)}else{assert!(!call.result.unwrap())}assert_eq!(call.receipt_spent,Default::default());assert_eq!(call.work_units_spent,0);assert_eq!(system,(0,0));assert_eq!(lane.entry.borrow_job_output_chunk(11,71,3,metadata.offset,length as u64).unwrap().as_ptr(),pointer);lane.receive(input,call.receipt_spent,call.work_units_spent,system,ActorGuestPhase::Dispatched)}
 let input=lane.checkout(RetainedCloneGrant{maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:0,..policy});let budget=lane.budget(input);let mut recipient=Default::default();let(call,system)=observe(||lane.entry.acknowledge_job_output_chunk_step(11,metadata.offset,length as u64,input,budget,&mut recipient,clock));assert!(call.result.unwrap());assert_eq!(call.receipt_spent,RetainedCloneProgress{copied_items:1,..Default::default()});assert_eq!(call.work_units_spent,law["acknowledgement"]["work"].as_u64().unwrap());assert_eq!(system,(0,0));assert_eq!(lane.entry.job_output_chunk.as_ref().unwrap().as_ptr(),pointer);assert!(lane.entry.borrow_job_output_chunk(11,71,3,metadata.offset,length as u64).is_none());lane.receive(input,call.receipt_spent,call.work_units_spent,system,ActorGuestPhase::Dispatched);
 }else{closed=metadata.output_closed;lane.receive(input,call.receipt_spent,call.work_units_spent,system,ActorGuestPhase::Dispatched)}if closed{break}assert!(turn<9999,"original borrowed output did not close")}
 assert!(closed);assert_eq!(received.as_slice(),expected.as_slice());assert_eq!(received_len,expected.len());let input=lane.checkout(policy);let budget=lane.budget(input);let mut recipient=Default::default();let(call,system)=observe(||lane.entry.acknowledge_job_output_step(11,input,budget,&mut recipient,clock));assert!(call.result.unwrap());lane.receive(input,call.receipt_spent,call.work_units_spent,system,ActorGuestPhase::Dispatched);let input=lane.checkout(policy);let budget=lane.budget(input);let mut recipient=Default::default();let(call,system)=observe(||lane.entry.close_jobs_step(input,budget,&mut recipient,clock,&mut EmptyOriginalJobs));assert!(call.result.unwrap());lane.receive(input,call.receipt_spent,call.work_units_spent,system,ActorGuestPhase::Dispatched);for turn in 0..10000{if lane.entry.terminal_is_empty(){break}let demand=lane.entry.context.retirement_demands(policy.maximum_copy_bytes).unwrap();let input=lane.checkout(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth.max(1)});let(call,system)=observe(||lane.entry.close_step(input));assert!(call.result.is_ok());lane.receive(input,call.receipt_spent,call.work_units_spent,system,ActorGuestPhase::Dispatched);assert!(turn<9999)}assert_eq!(lane.capacity,lane.released);assert_eq!(observe(||drop(lane.entry)).1,(0,0));let(original_input,system)=observe(||lane.host.take_dispatched_input().unwrap().unwrap());assert!(original_input.is_empty());assert_eq!(system,(0,0));assert_eq!(observe(||drop(original_input)).1,(0,0));assert_eq!(observe(||drop(lane.host)).1,(0,0));
 }
}
